const keys={};let moveTarget=null,focusTarget=null;
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k>='1'&&k<='5')switchHero(+k-1);if(k==='q')useSkill();if(k===' '&&started&&!paused)attack(active);if(k==='escape')togglePause()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelector('#start-btn').onclick=()=>deploy();document.querySelector('#intro-start').onclick=()=>{document.querySelector('#intro').classList.add('hidden');deploy()};document.querySelector('#pause-btn').onclick=togglePause;
function deploy(){if(!started){initWorld();started=true;document.querySelector('#intro').classList.add('hidden');document.querySelector('#match-state').textContent='LIVE · CORE WAR';document.querySelector('#start-btn').textContent='Retreat';document.querySelector('#start-btn').onclick=()=>{if(world.gameOver){document.querySelector('#intro').classList.remove('hidden');started=false;return}say('Hold the line. The battle is live.')}}paused=false;say('Squad deployed. Break through the east gate.');}
function togglePause(){if(!started)return;paused=!paused;document.querySelector('#pause-btn').textContent=paused?'Resume':'Pause';say(paused?'Simulation paused':'Battle resumed')}
function useSkill(){if(!started||paused||world.gameOver)return;const u=world.heroes[active],h=heroes[active];if(u.dead>0){say(`${h.name} is returning in ${Math.ceil(u.dead)}s`);return}if(u.skill>0){say(`${h.skill} recharging · ${Math.ceil(u.skill)}s`);return}const enemies=world.enemies.filter(e=>e.hp>0&&dist(u,e)<210);u.skill=h.cd;
 if(active===0){u.stealth=1.5;u.stealthStrike=0;world.effects.push({type:'ring',x:u.x,y:u.y,t:.8,color:'#ef795f'});say('Ghoststep · vanish, then strike to stun');}
 if(active===1){u.root=3.4;u.guard=3.4;let caught=0;for(const e of world.enemies)if(e.hp>0&&dist(u,e)<245){e.root=3.4;e.hp-=25;caught++}world.effects.push({type:'ring',x:u.x,y:u.y,t:1,color:'#8fb6d8'});say(`Stone Circle · ${caught} enemies rooted; armor tripled`);log(`Teneia rooted ${caught} foes.`, 'lime');}
 if(active===2){let target=nearest(u,world.enemies.filter(e=>e.hp>0));if(target){const d=dist(u,target);u.x+=((target.x-u.x)/Math.max(d,1))*Math.min(66,d);u.y+=((target.y-u.y)/Math.max(d,1))*Math.min(66,d);let bonus=inGrass(u)?2:1,damage=target.kind==='hero'?22:38;target.hp-=damage*bonus;target.stun=.35;world.effects.push({type:'slash',x:target.x,y:target.y,t:.4,color:'#d6aa6a'});say(`Maul · ${Math.round(damage*bonus)} damage${bonus===2?' · grass ambush!':''}`)}else say('Maul needs a target nearby');}
 if(active===3){let target=nearest(u,world.enemies.filter(e=>e.hp>0));if(target){target.hp-=45;target.stun=.3;world.effects.push({type:'shot',x:u.x,y:u.y,x2:target.x,y2:target.y,t:.4,color:'#e6d078'});say('Deadeye · armor-piercing shot')}else say('No target in sight');}
 if(active===4){let target=nearest(u,world.heroes.filter(a=>a.hp<a.max&&a.dead<=0));if(target){target.hp=Math.min(target.max,target.hp+55);target.shield=4;world.effects.push({type:'ring',x:target.x,y:target.y,t:.8,color:'#a7d29a'});say(`Verdant Pulse · ${target.name} restored + shield`);log('Mira mended the squad.')}else say('Your squad is already at full strength');}
}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function nearest(u,list){let n=null,d=1e9;for(const x of list){let z=dist(u,x);if(z<d){d=z;n=x}}return n}
function inGrass(u){return world.jungles.some(j=>Math.hypot(u.x-j.x,u.y-j.y)<j.r)}
function targetList(){return [...world.enemies.filter(e=>e.hp>0),...world.minions.filter(m=>m.side==='red'&&m.hp>0),...world.towers.filter(t=>t.side==='enemy'&&t.hp>0),...(world.cores.enemy>0?[{x:1325,y:400,hp:world.cores.enemy,kind:'core',side:'enemy'}]:[])]}
function attack(i){if(!started||paused||world.gameOver)return;const u=world.heroes[i];if(u.dead>0)return;const targets=targetList();let target=focusTarget&&focusTarget.hp>0?focusTarget:nearest(u,targets);if(!target){say('No enemy in range');return}if(dist(u,target)>u.range+28){if(i===active){moveTarget={x:target.x,y:target.y};say('Closing to attack range')}return}deal(u,target,i);}
function deal(u,t,i,damage){let power=damage||u.atk;let h=heroes[i];if(i===0&&u.speedBoost>0)power*=1.35;if(i===2&&inGrass(u))power*=2;if(t===focusTarget)focusTarget=null;if(t.kind==='core'){world.cores.enemy=Math.max(0,world.cores.enemy-power);log('Enemy core takes damage!')}else if(t.side==='enemy'&&t.max&&t.x===1225){t.hp=Math.max(0,t.hp-power);if(t.hp===0)log('Enemy tower destroyed!');}else{t.hp-=power;if(t.hp<=0&&world.enemies.includes(t)){kills++;log(`${h.name} dropped ${t.name}.`,'lime');t.dead=7;t.hp=0;}}u.attackFlash=.22;world.effects.push({type:'hit',x:t.x,y:t.y,t:.3,color:h.tone});if(i===0&&t.stun>0){u.speedBoost=2.2;u.defenseDown=2.2;}}
function move(u,x,y,dt){let dx=x-u.x,dy=y-u.y,d=Math.hypot(dx,dy);if(d>3){let step=Math.min(d,u.speed*dt);u.x+=dx/d*step;u.y+=dy/d*step;u.dir=dx>=0?1:-1}}
function update(dt){if(!started||paused||world.gameOver)return;elapsed+=dt;world.waveTimer-=dt;if(world.waveTimer<=0){world.wave++;world.waveTimer=24;for(let i=0;i<3;i++){world.minions.push({x:215,y:377+i*22,hp:42,max:42,atk:5,range:28,speed:57,side:'blue',timer:Math.random(),dead:0});world.minions.push({x:1185,y:423+i*22,hp:42,max:42,atk:5,range:28,speed:57,side:'red',timer:Math.random(),dead:0});}log(`Wave ${world.wave} marches into the ward.`);}
 const u=world.heroes[active];for(let i=0;i<5;i++){let a=world.heroes[i];a.timer-=dt;a.skill=Math.max(0,a.skill-dt);a.stun=Math.max(0,a.stun-dt);a.root=Math.max(0,a.root-dt);a.guard=Math.max(0,(a.guard||0)-dt);a.stealth=Math.max(0,(a.stealth||0)-dt);a.speedBoost=Math.max(0,(a.speedBoost||0)-dt);a.defenseDown=Math.max(0,(a.defenseDown||0)-dt);a.attackFlash=Math.max(0,a.attackFlash-dt);a.shield=Math.max(0,(a.shield||0)-dt);
 if(a.dead>0){a.dead-=dt;if(a.dead<=0){a.hp=a.max;a.x=255+(i%2)*30;a.y=300+Math.floor(i/2)*50;log(`${a.name} returned to the fight.`)}continue}if(a.stun>0||a.root>0)continue;
 if(i===active){let vx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),vy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(vx||vy){move(a,a.x+vx*100,a.y+vy*100,dt);moveTarget=null;}else if(moveTarget){move(a,moveTarget.x,moveTarget.y,dt);if(dist(a,moveTarget)<8)moveTarget=null;}if(keys[' ']){if(a.timer<=0){attack(i);a.timer=i===0&&a.speedBoost>0?.16:.68}}}
 else{let enemies=world.enemies.filter(e=>e.hp>0),allyHurt=nearest(a,world.heroes.filter(x=>x.hp<x.max-8&&x.dead<=0));let target=nearest(a,enemies);let mode=heroes[i].logic;if(mode==='SUSTAIN'&&allyHurt&&dist(a,allyHurt)>65)move(a,allyHurt.x,allyHurt.y,dt);else if(mode==='GUARD'&&dist(a,{x:270,y:400})>80)move(a,270+(i%2)*20,390+Math.floor(i/2)*30,dt);else if(mode==='SCOUT'&&dist(a,{x:450,y:200})>90)move(a,450+(elapsed%2)*50,220,dt);else if(target&&dist(a,target)>a.range*.8)move(a,target.x-(mode==='BACKLINE'?80:0),target.y,dt);if(a.timer<=0&&target&&dist(a,target)<a.range+10){deal(a,target,i);a.timer=i===0&&a.speedBoost>0?.22:1.05}if(a.skill<=0&&i!==1&&i!==4&&target&&dist(a,target)<140&&Math.random()<dt*.13){let was=active;active=i;useSkill();active=was;}}
 a.x=Math.max(80,Math.min(1320,a.x));a.y=Math.max(100,Math.min(700,a.y));}
 // Enemy heroes pursue the nearest living ally, respecting tower lane boundaries.
 for(const e of world.enemies){e.stun=Math.max(0,e.stun-dt);e.root=Math.max(0,e.root-dt);e.attackFlash=Math.max(0,e.attackFlash-dt);if(e.hp<=0){if(e.dead>0){e.dead-=dt;if(e.dead<=0){e.hp=e.max;e.x=1130+Math.random()*40;e.y=300+Math.random()*200}}continue}if(e.stun>0||e.root>0)continue;let target=nearest(e,world.heroes.filter(a=>a.hp>0&&a.dead<=0));if(!target)continue;if(dist(e,target)>e.range*.82)move(e,target.x+16,target.y,dt);if(e.timer<=0&&dist(e,target)<e.range+12){let def=target.guard>0?3:target.defenseDown>0?.5:1;let dmg=e.atk/def;if(target.shield>0)dmg*=.65;target.hp-=dmg;e.timer=e.range>100?1.35:1;target.attackFlash=.2;world.effects.push({type:'hit',x:target.x,y:target.y,t:.25,color:'#f07868'});if(target.hp<=0){target.hp=0;target.dead=7;log(`${target.name} is down.`,'red')}}e.timer-=dt;}
 // Lane minions march and fight.
 for(const m of world.minions){if(m.hp<=0)continue;let foes=world.minions.filter(n=>n.side!==m.side&&n.hp>0);let t=nearest(m,foes);if(t&&dist(m,t)<38){m.timer-=dt;if(m.timer<=0){t.hp-=m.atk;m.timer=1.2}}else{let dir=m.side==='blue'?1:-1;m.x+=dir*m.speed*dt;if(m.x>780&&m.side==='blue'||m.x<620&&m.side==='red'){let enemy=nearest(m,world.enemies.filter(e=>e.hp>0));if(enemy){t=enemy;if(dist(m,t)<45){m.timer-=dt;if(m.timer<=0){t.hp-=m.atk;m.timer=1.3}}}}}}
 // Defensive towers protect their side and punish dives.
 for(const tower of world.towers){if(tower.hp<=0)continue;tower.timer-=dt;let targets=tower.side==='ally'?[...world.enemies.filter(e=>e.hp>0),...world.minions.filter(m=>m.side==='red'&&m.hp>0)]:[...world.heroes.filter(a=>a.hp>0),...world.minions.filter(m=>m.side==='blue'&&m.hp>0)];let target=nearest(tower,targets);if(target&&dist(tower,target)<250&&tower.timer<=0){tower.timer=1.55;world.bullets.push({x:tower.x,y:tower.y,target,damage:13,side:tower.side,t:0,color:tower.side==='ally'?'#c9f36e':'#f07868'})}}
 for(const b of world.bullets){if(!b.target||b.target.hp<=0){b.dead=1;continue}let d=dist(b,b.target),step=dt*420;if(d<step){b.target.hp-=b.damage;if(b.target.hp<=0&&world.enemies.includes(b.target)){b.target.hp=0;b.target.dead=7;log(`${b.target.name} fell under tower fire.`,'lime')}b.dead=1}else{b.x+=(b.target.x-b.x)/d*step;b.y+=(b.target.y-b.y)/d*step}}world.bullets=world.bullets.filter(b=>!b.dead);
 for(const e of world.effects)e.t-=dt;world.effects=world.effects.filter(e=>e.t>0);world.minions=world.minions.filter(m=>m.hp>0||m.x>100&&m.x<1300);
 if(world.cores.enemy<=0)endGame(true);if(world.cores.ally<=0)endGame(false);updateUI();}
function endGame(win){world.gameOver=true;document.querySelector('#match-state').textContent=win?'VICTORY · VEYRA IS YOURS':'DEFEAT · THE WARD HAS FALLEN';say(win?'Enemy core destroyed · Veyra is yours':'Your core has fallen');log(win?'The enemy core is shattered. Victory.':'Your core has fallen.');document.querySelector('#start-btn').textContent='New match';}
function updateUI(){world.heroes.forEach((h,i)=>{const el=document.querySelector(`#hp-${i}`);if(el)el.style.width=`${Math.max(0,h.hp/h.max*100)}%`});const a=world.towers.find(t=>t.side==='ally'),e=world.towers.find(t=>t.side==='enemy');document.querySelector('#ally-core-label').textContent=`${Math.round(world.cores.ally)}%`;document.querySelector('#ally-core-bar').style.width=`${world.cores.ally}%`;document.querySelector('#enemy-core-label').textContent=`${Math.round(world.cores.enemy)}%`;document.querySelector('#enemy-core-bar').style.width=`${world.cores.enemy}%`;document.querySelector('#ally-tower-label').textContent=`${Math.round(a.hp/a.max*100)}%`;document.querySelector('#ally-tower-bar').style.width=`${a.hp/a.max*100}%`;const cd=document.querySelector('#skill-cd small');if(cd&&started){let c=world.heroes[active].skill;cd.textContent=c>0?`${Math.ceil(c)}s`:'READY';cd.style.color=c>0?'#889386':'#c5ee7c'}document.querySelector('.arena-title span').textContent=`DAY 01 / ${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;}

function draw(){const c=ctx;c.clearRect(0,0,world.w,world.h);c.fillStyle='#28332b';c.fillRect(0,0,world.w,world.h);
 // ruined paving and cracked stone field
 for(let y=0;y<world.h;y+=46)for(let x=0;x<world.w;x+=52){let n=(x*13+y*7)%29;c.fillStyle=n<8?'#303a31':n<17?'#2d372f':'#323c33';c.fillRect(x+1,y+1,49,43);c.strokeStyle='#202a23';c.lineWidth=1;c.strokeRect(x+1,y+1,49,43);if(n%5===1){c.strokeStyle='#252f28';c.beginPath();c.moveTo(x+8,y+7);c.lineTo(x+14,y+18);c.lineTo(x+10,y+28);c.stroke();}}
 // lane, borders, paving marks
 c.fillStyle='#41463a';c.fillRect(0,344,world.w,112);c.fillStyle='#4b4d40';c.fillRect(0,365,world.w,70);c.strokeStyle='#74725a';c.setLineDash([12,17]);c.lineWidth=2;c.beginPath();c.moveTo(20,400);c.lineTo(1380,400);c.stroke();c.setLineDash([]);
 // broken walls / architecture
 drawRuin(60,100,150,86,0);drawRuin(230,540,126,112,1);drawRuin(630,80,155,90,2);drawRuin(650,630,170,82,0);drawRuin(1050,88,125,104,1);drawRuin(1085,570,190,115,2);drawRuin(760,255,90,44,0);drawRuin(580,500,78,40,1);
 // jungle grass patches, Oola detection ripples
 world.jungles.forEach((g,i)=>{c.fillStyle='#223729';c.beginPath();c.ellipse(g.x,g.y,g.r,g.r*.72,0,0,Math.PI*2);c.fill();for(let j=0;j<90;j++){const ang=(j*2.399+i)*1,r=Math.sqrt((j*37%100)/100)*g.r*.92,x=g.x+Math.cos(ang)*r,y=g.y+Math.sin(ang)*r*.72;c.strokeStyle=j%3?'#476541':'#68834a';c.lineWidth=1.5;c.beginPath();c.moveTo(x,y+5);c.lineTo(x-3+(j%7),y-6-(j%5));c.stroke()}});
 // rubble and wreckage
 for(let i=0;i<42;i++){let x=(i*173+70)%world.w,y=(i*97+28)%world.h;if(Math.abs(y-400)<75)continue;c.fillStyle=i%3?'#515447':'#6a6654';c.save();c.translate(x,y);c.rotate(i*1.72);c.fillRect(-6,-4,12,8);c.fillStyle='#343b30';c.fillRect(-2,-2,7,5);c.restore()}
 // cores and towers
 drawCore(75,400,'ally');drawCore(1325,400,'enemy');world.towers.forEach(t=>drawTower(t));
 // map notches / boundaries
 c.strokeStyle='#718064';c.globalAlpha=.35;c.lineWidth=2;c.strokeRect(8,8,1384,784);c.globalAlpha=1;
 // target marker
 if(moveTarget){c.strokeStyle='#d5f48e';c.lineWidth=2;c.beginPath();c.arc(moveTarget.x,moveTarget.y,12+Math.sin(elapsed*8)*3,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(moveTarget.x-17,moveTarget.y);c.lineTo(moveTarget.x+17,moveTarget.y);c.moveTo(moveTarget.x,moveTarget.y-17);c.lineTo(moveTarget.x,moveTarget.y+17);c.stroke()}
 world.minions.forEach(m=>{if(m.hp<=0)return;drawUnit(m,m.side==='blue'?'#c5ed76':'#ee8877',false)});
 world.enemies.forEach(e=>{if(e.hp>0)drawUnit(e,e.color,true)});
 world.heroes.forEach((h,i)=>{if(h.hp>0)drawHero(h,i)});
 // projectiles and ability accents
 world.bullets.forEach(b=>{c.fillStyle=b.color;c.shadowColor=b.color;c.shadowBlur=10;c.beginPath();c.arc(b.x,b.y,5,0,Math.PI*2);c.fill();c.shadowBlur=0});world.effects.forEach(e=>{let alpha=Math.min(1,e.t*2);c.globalAlpha=alpha;c.strokeStyle=e.color;c.fillStyle=e.color;c.lineWidth=3;if(e.type==='ring'){c.beginPath();c.arc(e.x,e.y,38+(1-e.t)*55,0,Math.PI*2);c.stroke()}else if(e.type==='shot'){c.beginPath();c.moveTo(e.x,e.y);c.lineTo(e.x2,e.y2);c.stroke()}else{c.beginPath();c.arc(e.x,e.y,10+(1-e.t)*20,0,Math.PI*2);c.stroke()}c.globalAlpha=1});
 // minimap inset
 c.fillStyle='#111813dd';c.fillRect(1174,710,196,70);c.strokeStyle='#718064';c.strokeRect(1174,710,196,70);c.fillStyle='#7d7a64';c.fillRect(1182,740,180,9);world.heroes.forEach(h=>{if(h.hp>0){c.fillStyle='#c8f36a';c.fillRect(1184+h.x/world.w*175,733+h.y/world.h*42,4,4)}});world.enemies.forEach(e=>{if(e.hp>0){c.fillStyle='#f07868';c.fillRect(1184+e.x/world.w*175,733+e.y/world.h*42,4,4)}});c.fillStyle='#c8f36a';c.fillRect(1181,736,5,15);c.fillStyle='#f07868';c.fillRect(1353,736,5,15);
}
function drawRuin(x,y,w,h,variant){const c=ctx;c.fillStyle='#1c251f';c.fillRect(x+8,y+12,w,h);c.fillStyle=variant===1?'#555648':'#4a5043';c.fillRect(x,y,w,h);c.fillStyle='#68705a';c.fillRect(x,y,w,7);c.fillStyle='#252d26';c.fillRect(x+14,y+16,w-28,h-24);c.strokeStyle='#6b6d59';c.lineWidth=5;c.strokeRect(x+7,y+9,w-14,h-18);c.fillStyle='#30372e';for(let i=0;i<4;i++){let px=x+15+i*29;c.fillRect(px,y+18,11,h-33);c.fillStyle='#59604f';c.fillRect(px+3,y+22,3,h-40)}c.fillStyle='#88816a';c.beginPath();c.moveTo(x+w-30,y);c.lineTo(x+w-12,y-11);c.lineTo(x+w,y+2);c.fill()}
function drawTower(t){const c=ctx;if(t.hp<=0){c.fillStyle='#4b4639';c.fillRect(t.x-21,388,42,24);c.fillStyle='#69604b';c.beginPath();c.moveTo(t.x-26,390);c.lineTo(t.x,373);c.lineTo(t.x+24,390);c.fill();return}const ally=t.side==='ally';c.fillStyle='#171d18';c.beginPath();c.ellipse(t.x,t.y+15,32,14,0,0,Math.PI*2);c.fill();c.fillStyle=ally?'#718352':'#86584c';c.fillRect(t.x-19,t.y-31,38,47);c.fillStyle=ally?'#a2b377':'#bc796b';c.beginPath();c.moveTo(t.x-25,t.y-29);c.lineTo(t.x,t.y-55);c.lineTo(t.x+25,t.y-29);c.fill();c.fillStyle=ally?'#d2f47b':'#f18a72';c.shadowColor=c.fillStyle;c.shadowBlur=13;c.beginPath();c.arc(t.x,t.y-17,6,0,Math.PI*2);c.fill();c.shadowBlur=0;c.fillStyle='#1b211a';c.fillRect(t.x-23,t.y-66,46,5);c.fillStyle=ally?'#c8f36a':'#f07868';c.fillRect(t.x-23,t.y-66,46*Math.max(0,t.hp/t.max),5)}
